        String s2 = textValue.substring(end, length); 
        String s = s1 + ELLIPSIS + s2; 

        int l = gc.textExtent(s).x; 

        if (l < maxWidth) { 
            gc.dispose(); 
            return s; 
        } 
        start--; 
        end++; 
    } 
} 
