    HttpSession session = aRequest.getSession(); 
    ServletContext context = session.getServletContext(); 
    context.setAttribute(MOST_RECENT_TROUBLE_TICKET, troubleTicket);   
    troubleTicket.mailToWebmaster(); 
}
