public void logAndEmailSeriousProblem(Throwable ex, HttpServletRequest aRequest) 
{ 
    /* Define local variable. */ 
    TroubleTicket troubleTicket = new TroubleTicket(ex, aRequest); 

    /* Log message. */ 
    fLogger.severe("TOP LEVEL CATCHING Throwable."); 
